 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            colors = {}
            for y, x in cells:
                colors.setdefault(grid[y][x], []).append((y,x))
            boxes = {}
            for color, pts in colors.items():
                ys = [p[0] for p in pts]
                xs = [p[1] for p in pts]
                boxes[color] = (min(ys), max(ys), min(xs), max(xs))
            ordered = sorted(colors, key=lambda color: (-(boxes[color][1]-boxes[color][0]+1)*(boxes[color][3]-boxes[color][2]+1), color))
            mapping = {src: dst for src, dst in zip(ordered, reversed(ordered))}
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out
